-- create observation table.
CREATE TABLE BH_Observation (
	AD_Client_ID NUMBER(10) NOT NULL, 
	AD_Field_ID NUMBER(10) DEFAULT NULL, 
	AD_Org_ID NUMBER(10) NOT NULL, 
	AD_Table_ID NUMBER(10) DEFAULT NULL, 
	BH_Encounter_ID NUMBER(10) DEFAULT NULL, 
	BH_Observation_ID NUMBER(10) NOT NULL, 
	BH_Observation_UU VARCHAR2(36) DEFAULT NULL, 
	Created DATE DEFAULT SYSDATE NOT NULL, 
	CreatedBy NUMBER(10) NOT NULL, 
	IsActive CHAR(1) DEFAULT 'Y' CHECK (IsActive IN ('Y','N')) NOT NULL, 
	LineNo NUMBER(10) DEFAULT NULL, 
	Record_ID NUMBER(10) DEFAULT NULL, 
	Updated DATE DEFAULT SYSDATE NOT NULL, 
	UpdatedBy NUMBER(10) NOT NULL, 
	Value VARCHAR2(255) DEFAULT NULL, 
	CONSTRAINT BH_Observation_Key PRIMARY KEY (BH_Observation_ID), 
	CONSTRAINT BH_Observation_UU_idx UNIQUE (BH_Observation_UU)
); 
	
ALTER TABLE BH_Observation ADD CONSTRAINT ADClient_BHObservation FOREIGN KEY (AD_Client_ID) REFERENCES ad_client(ad_client_id) DEFERRABLE INITIALLY DEFERRED; 
ALTER TABLE BH_Observation ADD CONSTRAINT ADField_BHObservation FOREIGN KEY (AD_Field_ID) REFERENCES ad_field(ad_field_id) DEFERRABLE INITIALLY DEFERRED; 
ALTER TABLE BH_Observation ADD CONSTRAINT ADOrg_BHObservation FOREIGN KEY (AD_Org_ID) REFERENCES ad_org(ad_org_id) DEFERRABLE INITIALLY DEFERRED; 
ALTER TABLE BH_Observation ADD CONSTRAINT ADTable_BHObservation FOREIGN KEY (AD_Table_ID) REFERENCES ad_table(ad_table_id) DEFERRABLE INITIALLY DEFERRED; 
ALTER TABLE BH_Observation ADD CONSTRAINT BHEncounter_BHObservation FOREIGN KEY (BH_Encounter_ID) REFERENCES bh_encounter(bh_encounter_id) DEFERRABLE INITIALLY DEFERRED;
 
